# ruff: noqa: E501

from typing import Literal, cast

SupportedLocale = Literal["it", "en", "es", "de", "fr"]
SUPPORTED_LOCALES = frozenset({"it", "en", "es", "de", "fr"})
LANGUAGE_NAMES: dict[SupportedLocale, str] = {
    "it": "Italian",
    "en": "English",
    "es": "Spanish",
    "de": "German",
    "fr": "French",
}


def normalize_locale(value: str | None) -> SupportedLocale:
    code = (
        (value if isinstance(value, str) else "it")
        .strip()
        .lower()
        .replace("_", "-")
        .split("-", 1)[0]
    )
    return cast(SupportedLocale, code if code in SUPPORTED_LOCALES else "it")


def language_name(value: str | None) -> str:
    return LANGUAGE_NAMES[normalize_locale(value)]


