def has_translation(key: str, locale: str | None) -> bool:
    """True when [key] exists for [locale] itself (no Italian fallback)."""
    return key in _MESSAGES and normalize_locale(locale) in _MESSAGES[key]


def translate(key: str, locale: str | None, **values: object) -> str:
    normalized = normalize_locale(locale)
    template = _MESSAGES[key].get(normalized, _MESSAGES[key]["it"])
    return template.format(**values)
